Bug: `Commission` in this Delphi unit accepts a negative percentage. Fix it.

```delphi
unit Percentages;

interface

function ApplyDiscount(const AAmount, APercent: Currency): Currency;
function ApplySurcharge(const AAmount, APercent: Currency): Currency;
function Commission(const AAmount, APercent: Currency): Currency;

implementation

uses
  System.SysUtils;

function ApplyDiscount(const AAmount, APercent: Currency): Currency;
begin
  if (APercent < 0) or (APercent > 100) then
    raise EArgumentOutOfRangeException.Create('Percent must be between 0 and 100');
  Result := AAmount - AAmount * APercent / 100;
end;

function ApplySurcharge(const AAmount, APercent: Currency): Currency;
begin
  if (APercent < 0) or (APercent > 100) then
    raise EArgumentOutOfRangeException.Create('Percent must be between 0 and 100');
  Result := AAmount + AAmount * APercent / 100;
end;

function Commission(const AAmount, APercent: Currency): Currency;
begin
  if APercent > 100 then
    raise EArgumentOutOfRangeException.Create('Percent must be between 0 and 100');
  Result := AAmount * APercent / 100;
end;

end.
```

The rule "a percentage goes from 0 to 100" is written three times, and the copy in `Commission` is the one that drifted. Fixing only that line would leave three copies waiting for the next drift. Fix it where the rule should live: one `CheckPercent`, called by the three functions - the bug is gone, and it cannot come back in only one of them.

```delphi
unit Percentages;

interface

function ApplyDiscount(const AAmount, APercent: Currency): Currency;
function ApplySurcharge(const AAmount, APercent: Currency): Currency;
function Commission(const AAmount, APercent: Currency): Currency;

implementation

uses
  System.SysUtils;

// The one place that knows what a valid percentage is
procedure CheckPercent(const APercent: Currency);
begin
  if (APercent < 0) or (APercent > 100) then
    raise EArgumentOutOfRangeException.Create('Percent must be between 0 and 100');
end;

function ApplyDiscount(const AAmount, APercent: Currency): Currency;
begin
  CheckPercent(APercent);
  Result := AAmount - AAmount * APercent / 100;
end;

function ApplySurcharge(const AAmount, APercent: Currency): Currency;
begin
  CheckPercent(APercent);
  Result := AAmount + AAmount * APercent / 100;
end;

function Commission(const AAmount, APercent: Currency): Currency;
begin
  CheckPercent(APercent);
  Result := AAmount * APercent / 100;
end;

end.
```

Add a function to this Delphi unit that reads the year and the number back from an export file name.

```delphi
unit ExportNames;

interface

function ExportFileName(const AYear, ANumber: Integer): string;
function ArchiveFileName(const AYear, ANumber: Integer): string;

implementation

uses
  System.SysUtils;

function ExportFileName(const AYear, ANumber: Integer): string;
begin
  Result := Format('export-%d-%.4d.csv', [AYear, ANumber]);
end;

function ArchiveFileName(const AYear, ANumber: Integer): string;
begin
  Result := 'export-' + IntToStr(AYear) + '-' + IntToStr(ANumber) + '.csv';
end;

end.
```

There are already two writers of this name and they disagree: `ExportFileName` pads the number to four digits (`export-2026-0007.csv`) and `ArchiveFileName` does not (`export-2026-7.csv`). A reader can only be the inverse of one writer. So: one function composes the name, the other caller uses it, and the reader is written as its inverse, sharing the same prefix and suffix - the three can no longer drift apart. The reader still accepts the old unpadded names, since `TryStrToInt('7')` works.

```delphi
unit ExportNames;

interface

function ExportFileName(const AYear, ANumber: Integer): string;
function ArchiveFileName(const AYear, ANumber: Integer): string;
function TryParseExportFileName(const AName: string; out AYear, ANumber: Integer): Boolean;

implementation

uses
  System.SysUtils;

const
  ExportPrefix = 'export-';
  ExportSuffix = '.csv';

// The one writer of the name; TryParseExportFileName is its inverse
function ExportFileName(const AYear, ANumber: Integer): string;
begin
  Result := Format(ExportPrefix + '%d-%.4d' + ExportSuffix, [AYear, ANumber]);
end;

function ArchiveFileName(const AYear, ANumber: Integer): string;
begin
  Result := ExportFileName(AYear, ANumber);
end;

function TryParseExportFileName(const AName: string; out AYear, ANumber: Integer): Boolean;
var
  Middle: string;
  Dash: Integer;
begin
  AYear := 0;
  ANumber := 0;
  Result := False;
  if not (AName.StartsWith(ExportPrefix) and AName.EndsWith(ExportSuffix)) then
    Exit;
  Middle := Copy(AName, Length(ExportPrefix) + 1,
    Length(AName) - Length(ExportPrefix) - Length(ExportSuffix));
  Dash := Pos('-', Middle);
  if Dash = 0 then
    Exit;
  Result := TryStrToInt(Copy(Middle, 1, Dash - 1), AYear) and
    TryStrToInt(Copy(Middle, Dash + 1, MaxInt), ANumber);
end;

end.
```

Add a function to this Delphi unit that turns a day key back into a date.

```delphi
unit DayKeys;

interface

function DayKey(const ADate: TDateTime): string;
function ArchiveDayKey(const ADate: TDateTime): string;

implementation

uses
  System.SysUtils, System.DateUtils;

function DayKey(const ADate: TDateTime): string;
begin
  Result := FormatDateTime('yyyymmdd', ADate);
end;

function ArchiveDayKey(const ADate: TDateTime): string;
begin
  Result := Format('%d%d%d', [YearOf(ADate), MonthOf(ADate), DayOf(ADate)]);
end;

end.
```

There are already two writers of the key, and they disagree: `DayKey` writes `20260307` and `ArchiveDayKey` writes `202637`. The second one cannot be read back at all: `2026111` could be the 1st of November or the 11th of January. A reader can only be the inverse of one writer. So `DayKey` is the one writer, `ArchiveDayKey` calls it, and the reader is written as its inverse: fixed width, every part checked, and `TryEncodeDate` refuses a day that does not exist.

```delphi
unit DayKeys;

interface

function DayKey(const ADate: TDateTime): string;
function ArchiveDayKey(const ADate: TDateTime): string;
function TryDayKeyToDate(const AKey: string; out ADate: TDateTime): Boolean;

implementation

uses
  System.SysUtils;

// The one writer of a day key (yyyymmdd); TryDayKeyToDate is its inverse
function DayKey(const ADate: TDateTime): string;
begin
  Result := FormatDateTime('yyyymmdd', ADate);
end;

function ArchiveDayKey(const ADate: TDateTime): string;
begin
  Result := DayKey(ADate);
end;

function TryDayKeyToDate(const AKey: string; out ADate: TDateTime): Boolean;
var
  Y, M, D: Integer;
begin
  ADate := 0;
  Result := (Length(AKey) = 8) and TryStrToInt(Copy(AKey, 1, 4), Y) and
    TryStrToInt(Copy(AKey, 5, 2), M) and TryStrToInt(Copy(AKey, 7, 2), D) and
    (Y > 0) and (M > 0) and (D > 0) and TryEncodeDate(Y, M, D, ADate);
end;

end.
```

Codes now also arrive with spaces inside (`k - 100`). Change `NormalizeCode` in this Delphi unit so that it ignores every space.

```delphi
unit CodeRules;

interface

function NormalizeCode(const ACode: string): string;
function IsDiscontinued(const ACode: string): Boolean;
function IsSeasonal(const ACode: string): Boolean;

implementation

uses
  System.SysUtils, System.StrUtils;

const
  Discontinued: array[0..1] of string = ('K-100', 'K-220');
  Seasonal: array[0..1] of string = ('W-010', 'W-020');

function NormalizeCode(const ACode: string): string;
begin
  Result := UpperCase(Trim(ACode));
end;

function IsDiscontinued(const ACode: string): Boolean;
begin
  Result := IndexStr(NormalizeCode(ACode), Discontinued) >= 0;
end;

function IsSeasonal(const ACode: string): Boolean;
begin
  Result := IndexStr(NormalizeCode(ACode), Seasonal) >= 0;
end;

end.
```

`NormalizeCode` is shared: `IsDiscontinued` and `IsSeasonal` both depend on it. Before changing a shared helper, pin down what its callers already do with tests and run them on the current code - they pass. Then add a test for the new rule (it fails on the current code), make the change, and run them all again: the new rule must not move anything that already worked.

First the tests, with DUnitX:

```delphi
unit CodeRulesTests;

interface

uses
  DUnitX.TestFramework;

type
  [TestFixture]
  TCodeRulesTests = class
  public
    // What already worked, pinned BEFORE the change: both callers of NormalizeCode
    [Test]
    procedure DiscontinuedIgnoresCaseAndOuterSpaces;
    [Test]
    procedure SeasonalKnowsOnlyItsCodes;
    // The new rule
    [Test]
    procedure InnerSpacesAreIgnored;
  end;

implementation

uses
  CodeRules;

procedure TCodeRulesTests.DiscontinuedIgnoresCaseAndOuterSpaces;
begin
  Assert.IsTrue(IsDiscontinued(' k-100 '));
  Assert.IsFalse(IsDiscontinued('K-101'));
end;

procedure TCodeRulesTests.SeasonalKnowsOnlyItsCodes;
begin
  Assert.IsTrue(IsSeasonal('w-020'));
  Assert.IsFalse(IsSeasonal('K-100'));
end;

procedure TCodeRulesTests.InnerSpacesAreIgnored;
begin
  Assert.IsTrue(IsDiscontinued('k - 100'));
  Assert.AreEqual('W-010', NormalizeCode(' w - 010 '));
end;

initialization
  TDUnitX.RegisterTestFixture(TCodeRulesTests);

end.
```

Then the change:

```delphi
unit CodeRules;

interface

function NormalizeCode(const ACode: string): string;
function IsDiscontinued(const ACode: string): Boolean;
function IsSeasonal(const ACode: string): Boolean;

implementation

uses
  System.SysUtils, System.StrUtils;

const
  Discontinued: array[0..1] of string = ('K-100', 'K-220');
  Seasonal: array[0..1] of string = ('W-010', 'W-020');

function NormalizeCode(const ACode: string): string;
begin
  // every space goes, inside included: ' k - 100 ' -> 'K-100'
  Result := UpperCase(ACode.Replace(' ', ''));
end;

function IsDiscontinued(const ACode: string): Boolean;
begin
  Result := IndexStr(NormalizeCode(ACode), Discontinued) >= 0;
end;

function IsSeasonal(const ACode: string): Boolean;
begin
  Result := IndexStr(NormalizeCode(ACode), Seasonal) >= 0;
end;

end.
```

A `TLayout` is created with `HitTest = False`: FireMonkey treats it as a container, not as a click target. A click on it is never given to it - it goes to whatever lies under the layout - so its `OnClick` never runs. Turn `HitTest` on, in the Object Inspector or in code. (`TLabel` is created the same way; `TRectangle`, `TText`, `TImage` and the buttons start with `HitTest = True`.)

```delphi
unit CardSetup;

interface

uses
  System.Classes, FMX.Layouts;

procedure MakeClickable(const ACard: TLayout; const AOnClick: TNotifyEvent);

implementation

procedure MakeClickable(const ACard: TLayout; const AOnClick: TNotifyEvent);
begin
  // a TLayout is created with HitTest = False: a container, not a click target
  ACard.HitTest := True;
  ACard.OnClick := AOnClick;
end;

end.
```

FireMonkey asks the children first, from the top-most one down: the first child under the point with `HitTest = True` gets the click, and the card never hears of it. `TText` and `TImage` are created with `HitTest = True`, so they take the click. The icon does too, even inside a layout whose own `HitTest` is off, because the layout passes the question on to its children. Content that is only decoration should not be a click target: switch its `HitTest` off all the way down. A child that must keep its own click - a button inside the card - would be left out.

```delphi
unit CardContent;

interface

uses
  FMX.Controls;

// Lets the clicks on a card's decorative content reach the card itself
procedure LetClicksThrough(const ACard: TControl);

implementation

procedure LetClicksThrough(const ACard: TControl);
var
  Child: TControl;
begin
  for Child in ACard.Controls do
  begin
    Child.HitTest := False;
    // content nested in a layout would still take the click: go all the way down
    LetClicksThrough(Child);
  end;
end;

end.
```

A FireMonkey `TLabel` is created with `HitTest = False`: clicks go through it to whatever is underneath, so its `OnClick` never runs. Turn `HitTest` on; a hand cursor tells the user it is clickable.

```delphi
unit LinkLabel;

interface

uses
  System.Classes, FMX.StdCtrls;

procedure MakeLink(const ALabel: TLabel; const AOnClick: TNotifyEvent);

implementation

uses
  System.UITypes;

procedure MakeLink(const ALabel: TLabel; const AOnClick: TNotifyEvent);
begin
  // a FireMonkey TLabel is created with HitTest = False: clicks go through it
  ALabel.HitTest := True;
  ALabel.Cursor := crHandPoint;
  ALabel.OnClick := AOnClick;
end;

end.
```

FireMonkey decides who gets a click by the control's rectangle, not by what it paints: `Opacity = 0`, no fill or a transparent colour change nothing. A `Visible` overlay on top keeps taking every click, so the buttons under it never get one. Hide it when it is not in use (`Visible := False`; a disabled control is skipped as well); while it shows, blocking the clicks is exactly its job. If an overlay must stay visible and still let the clicks through, set its `HitTest` to `False`.

```delphi
unit BusyOverlay;

interface

uses
  FMX.Objects;

procedure ShowBusy(const AOverlay: TRectangle; const ABusy: Boolean);

implementation

procedure ShowBusy(const AOverlay: TRectangle; const ABusy: Boolean);
begin
  // FireMonkey hit-tests the control's rectangle, not its pixels: a transparent
  // overlay that stays Visible keeps taking every click. Hide it when idle;
  // while it shows, blocking the clicks is what it is for.
  AOverlay.Visible := ABusy;
end;

end.
```

Ask FireMonkey the same question the form asks on every click: `ObjectAtPoint`. It is protected in `TControl`, but public through the `IControl` interface that every control implements. The rule it follows:

1. A control that is not `Visible` or not enabled is skipped, children included.
2. The children are asked first, from the top-most one down; the first that answers gets the click.
3. Only when no child answers does the control itself get it - if the point is inside its rectangle and its `HitTest` is `True`.
4. The rectangle counts, not the painted pixels: a transparent control on top still takes the click.

`nil` means none of them takes it: the click goes to whatever lies under `ARoot`. The point is in screen coordinates.

```delphi
unit ClickProbe;

interface

uses
  System.Types, FMX.Types, FMX.Controls;

// The control that gets a click at AScreenPoint, among ARoot and its children
// (nil = none of them: the click goes to whatever is under ARoot)
function ControlAt(const ARoot: TControl; const AScreenPoint: TPointF): TFmxObject;

implementation

function ControlAt(const ARoot: TControl; const AScreenPoint: TPointF): TFmxObject;
var
  Target: IControl;
begin
  // the question the form itself asks on every click; ObjectAtPoint is
  // protected in TControl and public through IControl
  Target := (ARoot as IControl).ObjectAtPoint(AScreenPoint);
  if Target = nil then
    Result := nil
  else
    Result := Target.GetObject;
end;

end.
```

Add a function `CustomerLabel(const AFirst, ALast: string): string` to this Delphi unit. It returns `Customer: ` followed by the customer's full name.

```delphi
unit CustomerText;

interface

function FullName(const AFirst, ALast: string): string;

implementation

uses
  System.SysUtils;

function FullName(const AFirst, ALast: string): string;
begin
  Result := Trim(Trim(AFirst) + ' ' + Trim(ALast));
end;

end.
```

Before writing it, look at what the unit already has: `FullName` builds exactly that name - it trims both parts and leaves no stray space when one of them is empty. `CustomerLabel` calls it instead of building the name again: a second copy would give a different answer the first time someone changes how names are built.

```delphi
unit CustomerText;

interface

function FullName(const AFirst, ALast: string): string;
function CustomerLabel(const AFirst, ALast: string): string;

implementation

uses
  System.SysUtils;

function FullName(const AFirst, ALast: string): string;
begin
  Result := Trim(Trim(AFirst) + ' ' + Trim(ALast));
end;

function CustomerLabel(const AFirst, ALast: string): string;
begin
  Result := 'Customer: ' + FullName(AFirst, ALast);
end;

end.
```

In this Delphi unit, add `IsSeasonal(const ACode: string): Boolean` for the codes S-010 and S-020.

